import ast, base64, hashlib, json, pathlib, zipfile, zlib
import xml.etree.ElementTree as ET
ROOT = pathlib.Path(__file__).resolve().parents[1]
VERSION = '2026.10.13.156'
PAYLOAD = ''
patch = json.loads(zlib.decompress(base64.b64decode(PAYLOAD)))
base = ROOT / 'zips/plugin.video.xship/plugin.video.xship-2026.10.12.150.zip'
out = ROOT / ('zips/plugin.video.xship/plugin.video.xship-' + VERSION + '.zip')
with zipfile.ZipFile(base) as old, zipfile.ZipFile(out, 'w', zipfile.ZIP_DEFLATED) as new:
    for item in old.infolist():
        data = patch.pop(item.filename, None)
        new.writestr(item, data.encode('utf-8') if data is not None else old.read(item.filename))
    for name, text in patch.items():
        new.writestr(name, text.encode('utf-8'))
with zipfile.ZipFile(out) as z:
    assert z.testzip() is None
    assert ET.fromstring(z.read('plugin.video.xship/addon.xml')).attrib['version'] == VERSION
    for name in ['service.py', 'resources/lib/player.py', 'resources/lib/hls_prebuffer.py', 'resources/lib/stream_playback.py']:
        ast.parse(z.read('plugin.video.xship/' + name))
    service = z.read('plugin.video.xship/service.py').decode()
    assert "_XSHIP_CHANGELOG_BUILD = '" + VERSION + "'" in service
    settings = ET.fromstring(z.read('plugin.video.xship/resources/settings.xml'))
    size = next(e for e in settings.iter('setting') if e.get('id') == 'playback.hls_prebuffer_mb')
    assert size.get('range') == '16,16,512'
    (ROOT / 'zips/plugin.video.xship/changelog.txt').write_bytes(z.read('plugin.video.xship/changelog.txt'))
print('Validated release:', out)
